#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <nb.h>

#define N 28
#define NUM_PAL 12

struct BrickColor {
  int code;
  const char *name;
  int r, g, b;
  double L, a, b_lab;
};

static struct BrickColor PAL[NUM_PAL] = {
  {  1, "White",             244, 244, 244, 0, 0, 0 },
  {  2, "Bright Yellow",     242, 205,  55, 0, 0, 0 },
  {  3, "Bright Orange",     254, 138,  24, 0, 0, 0 },
  {  4, "Bright Red",        201,  26,   9, 0, 0, 0 },
  {  5, "Tan / Brick Yellow",228, 205, 158, 0, 0, 0 },
  {  6, "Dark Azur",           7, 139, 201, 0, 0, 0 },
  {  7, "Bright Blue",         0,  85, 191, 0, 0, 0 },
  {  8, "Earth Blue (Navy)",  10,  52,  99, 0, 0, 0 },
  {  9, "Bright Green",       75, 159,  74, 0, 0, 0 },
  { 10, "Light Bluish Grey", 160, 165, 169, 0, 0, 0 },
  { 11, "Dark Bluish Grey",  108, 110, 104, 0, 0, 0 },
  { 12, "Black",              27,  42,  52, 0, 0, 0 },
};

static double srgb_to_lin(double c) {
  c /= 255.0;
  return (c <= 0.04045) ? (c / 12.92) : pow((c + 0.055) / 1.055, 2.4);
}

static double lab_f(double t) {
  return (t > 0.008856) ? pow(t, 1.0 / 3.0) : (7.787 * t + 16.0 / 116.0);
}

static void rgb_to_lab(double r, double g, double b, double *L, double *a, double *bl) {
  double rl = srgb_to_lin(r), gl = srgb_to_lin(g), blin = srgb_to_lin(b);
  double X = (0.4124 * rl + 0.3576 * gl + 0.1805 * blin) / 0.95047;
  double Y = (0.2126 * rl + 0.7152 * gl + 0.0722 * blin) / 1.00000;
  double Z = (0.0193 * rl + 0.1192 * gl + 0.9505 * blin) / 1.08883;
  double fx = lab_f(X), fy = lab_f(Y), fz = lab_f(Z);
  *L  = 116.0 * fy - 16.0;
  *a  = 500.0 * (fx - fy);
  *bl = 200.0 * (fy - fz);
}

static double clamp255(double v) {
  return v < 0.0 ? 0.0 : (v > 255.0 ? 255.0 : v);
}

/* Procedural continuous-tone RGB + relief height generator */
static void sample_art(int scene, int x, int y, double *r, double *g, double *b, int *plates) {
  double u = (double)x / (N - 1);
  double v = (double)y / (N - 1); /* 0 = top, 1 = bottom */

  if (scene == 0) {
    /* Great Wave & Crimson Sun */
    double sx = u - 0.72, sy = v - 0.26;
    double sun_d = sqrt(sx * sx + sy * sy);
    double wave_crest = 0.48 + 0.18 * sin(u * 5.5 - 0.8) - 0.12 * cos(u * 11.0);
    if (v > wave_crest) {
      double depth = (v - wave_crest) / (1.0 - wave_crest);
      int foam = fabs(v - wave_crest) < 0.055 || (sin(u * 24.0 + v * 14.0) > 0.78 && depth < 0.35);
      if (foam) {
        *r = 240; *g = 244; *b = 248; *plates = 4;
      } else {
        *r = 12 + 30 * (1.0 - depth);
        *g = 65 + 95 * (1.0 - depth);
        *b = 130 + 95 * (1.0 - depth);
        *plates = depth < 0.4 ? 3 : 2;
      }
    } else if (sun_d < 0.16) {
      *r = 220; *g = 45 + 110 * (sun_d / 0.16); *b = 25; *plates = 3;
    } else {
      /* Warm dusk sky gradient */
      *r = 235 - 75 * (1.0 - v);
      *g = 205 - 55 * (1.0 - v);
      *b = 145 + 45 * (1.0 - v);
      *plates = 1;
    }
  } else if (scene == 1) {
    /* Nordic Aurora & Mountain Peaks */
    double peak = 0.56 - 0.22 * fabs(sin(u * 3.8 + 0.4)) - 0.08 * cos(u * 9.0);
    if (v > peak) {
      int snow = (v - peak) < 0.11 + 0.04 * sin(u * 15.0);
      *r = snow ? 235 : 85;
      *g = snow ? 240 : 92;
      *b = snow ? 245 : 102;
      *plates = snow ? 4 : 3;
    } else {
      double band = (v - (0.24 + 0.08 * sin(u * 6.2))) / 0.11;
      double aurora = exp(-band * band);   /* not pow(band, 2): xcc's pow gives NaN for a negative base */
      *r = 15 + 55 * aurora;
      *g = 38 + 165 * aurora;
      *b = 85 + 90 * aurora;
      *plates = aurora > 0.5 ? 2 : 1;
    }
  } else {
    /* Spiral Galaxy & Nebula */
    double dx = u - 0.5, dy = v - 0.5;
    double rad = sqrt(dx * dx + dy * dy);
    double ang = atan2(dy, dx);
    double arm = 0.5 + 0.5 * cos(2.0 * ang - rad * 15.0);
    double core = exp(-rad * rad * 18.0);
    double glow = exp(-rad * 3.2) * arm;
    *r = clamp255(20 + 230 * core + 180 * glow);
    *g = clamp255(28 + 200 * core + 95 * glow);
    *b = clamp255(55 + 140 * core + 210 * exp(-rad * 2.2));
    *plates = core > 0.45 ? 4 : (glow > 0.35 ? 3 : (rad < 0.38 ? 2 : 1));
  }
}

static double imgR[N][N], imgG[N][N], imgB[N][N];
static double origR[N][N], origG[N][N], origB[N][N];   /* the artwork before any diffusion */
static int chosen[N][N], height_plates[N][N];

int main(void) {
  int scene = (int)nb_get_int("mosaic_scene", 0);
  int use_lab = (int)nb_get_int("mosaic_metric", 1);
  double dither = nb_get_number("mosaic_dither", 0.75);

  for (int p = 0; p < NUM_PAL; p++) {
    rgb_to_lab(PAL[p].r, PAL[p].g, PAL[p].b, &PAL[p].L, &PAL[p].a, &PAL[p].b_lab);
  }

  for (int y = 0; y < N; y++) {
    for (int x = 0; x < N; x++) {
      sample_art(scene, x, y, &imgR[y][x], &imgG[y][x], &imgB[y][x], &height_plates[y][x]);
      origR[y][x] = clamp255(imgR[y][x]);
      origG[y][x] = clamp255(imgG[y][x]);
      origB[y][x] = clamp255(imgB[y][x]);
    }
  }

  int counts[NUM_PAL] = {0};

  /* Floyd-Steinberg error-diffusion pass */
  for (int y = 0; y < N; y++) {
    for (int x = 0; x < N; x++) {
      double r = clamp255(imgR[y][x]);
      double g = clamp255(imgG[y][x]);
      double b = clamp255(imgB[y][x]);

      double L, a, bl;
      rgb_to_lab(r, g, b, &L, &a, &bl);

      int best = 0;
      double best_d = 1e18;
      for (int p = 0; p < NUM_PAL; p++) {
        double d;
        if (use_lab) {
          double dL = L - PAL[p].L, da = a - PAL[p].a, db = bl - PAL[p].b_lab;
          d = dL * dL + da * da + db * db;
        } else {
          double dr = r - PAL[p].r, dg = g - PAL[p].g, db = b - PAL[p].b;
          d = dr * dr + dg * dg + db * db;
        }
        if (d < best_d) { best_d = d; best = p; }
      }

      chosen[y][x] = best;
      counts[best]++;

      /* Diffuse RGB quantization error to 4 neighbors */
      double er = (r - PAL[best].r) * dither;
      double eg = (g - PAL[best].g) * dither;
      double eb = (b - PAL[best].b) * dither;

      if (x + 1 < N) {
        imgR[y][x + 1] += er * (7.0 / 16.0);
        imgG[y][x + 1] += eg * (7.0 / 16.0);
        imgB[y][x + 1] += eb * (7.0 / 16.0);
      }
      if (y + 1 < N) {
        if (x > 0) {
          imgR[y + 1][x - 1] += er * (3.0 / 16.0);
          imgG[y + 1][x - 1] += eg * (3.0 / 16.0);
          imgB[y + 1][x - 1] += eb * (3.0 / 16.0);
        }
        imgR[y + 1][x] += er * (5.0 / 16.0);
        imgG[y + 1][x] += eg * (5.0 / 16.0);
        imgB[y + 1][x] += eb * (5.0 / 16.0);
        if (x + 1 < N) {
          imgR[y + 1][x + 1] += er * (1.0 / 16.0);
          imgG[y + 1][x + 1] += eg * (1.0 / 16.0);
          imgB[y + 1][x + 1] += eb * (1.0 / 16.0);
        }
      }
    }
  }

  /* Two honest errors against the original artwork. Close up: each stud's colour
     against its pixel. From a distance: each 3 x 3 patch of studs, its light mixed
     (averaged in linear RGB, as the eye blends it), against the same patch of art. */
  double stud_de = 0.0, patch_de = 0.0;
  for (int y = 0; y < N; y++) {
    for (int x = 0; x < N; x++) {
      double L1, a1, b1, L2, a2, b2;
      struct BrickColor *c = &PAL[chosen[y][x]];
      rgb_to_lab(origR[y][x], origG[y][x], origB[y][x], &L1, &a1, &b1);
      stud_de += sqrt((L1 - c->L) * (L1 - c->L) + (a1 - c->a) * (a1 - c->a) + (b1 - c->b_lab) * (b1 - c->b_lab));

      double art[3] = {0, 0, 0}, bricks[3] = {0, 0, 0};
      int k = 0;
      for (int dy = -1; dy <= 1; dy++) {
        for (int dx = -1; dx <= 1; dx++) {
          int yy = y + dy, xx = x + dx;
          if (yy < 0 || xx < 0 || yy >= N || xx >= N) continue;
          struct BrickColor *q = &PAL[chosen[yy][xx]];
          art[0] += srgb_to_lin(origR[yy][xx]); art[1] += srgb_to_lin(origG[yy][xx]); art[2] += srgb_to_lin(origB[yy][xx]);
          bricks[0] += srgb_to_lin(q->r); bricks[1] += srgb_to_lin(q->g); bricks[2] += srgb_to_lin(q->b);
          k++;
        }
      }
      for (int i = 0; i < 3; i++) {   /* back to 0..255 sRGB for rgb_to_lab */
        double la = art[i] / k, lb = bricks[i] / k;
        art[i] = 255.0 * (la <= 0.0031308 ? 12.92 * la : 1.055 * pow(la, 1.0 / 2.4) - 0.055);
        bricks[i] = 255.0 * (lb <= 0.0031308 ? 12.92 * lb : 1.055 * pow(lb, 1.0 / 2.4) - 0.055);
      }
      rgb_to_lab(art[0], art[1], art[2], &L1, &a1, &b1);
      rgb_to_lab(bricks[0], bricks[1], bricks[2], &L2, &a2, &b2);
      patch_de += sqrt((L1 - L2) * (L1 - L2) + (a1 - a2) * (a1 - a2) + (b1 - b2) * (b1 - b2));
    }
  }
  stud_de /= N * N;
  patch_de /= N * N;

  printf("=== Perceptual CIELAB Brick Mosaic & Relief Compiler ===\n");
  printf("Canvas: %dx%d studs (%d top studs) | Metric: %s | Dither: %.0f%%\n",
         N, N, N * N, use_lab ? "CIE L*a*b* (Delta E*ab)" : "Naive sRGB Euclidean", dither * 100.0);
  printf("Colour error (Delta E*ab) against the original art:\n");
  printf("  close up, per stud:           %6.2f\n", stud_de);
  printf("  from a distance, per 3x3 patch: %4.2f\n\n", patch_de);

  printf("%-4s %-22s %10s\n", "ID", "Brick Colour", "1x1 Studs");
  printf("----------------------------------------\n");
  for (int p = 0; p < NUM_PAL; p++) {
    if (counts[p] > 0) {
      printf("#%-3d %-22s %10d\n", PAL[p].code, PAL[p].name, counts[p]);
    }
  }

  static char json[65536];
  int pos = 0;
  pos += snprintf(json + pos, sizeof(json) - pos,
    "{\"n\":%d,\"studDe\":%.2f,\"patchDe\":%.2f,\"metric\":\"%s\",\"palette\":[",
    N, stud_de, patch_de, use_lab ? "CIELAB" : "sRGB");
  for (int p = 0; p < NUM_PAL; p++) {
    pos += snprintf(json + pos, sizeof(json) - pos,
      "%s{\"name\":\"%s\",\"r\":%d,\"g\":%d,\"b\":%d,\"count\":%d}",
      p ? "," : "", PAL[p].name, PAL[p].r, PAL[p].g, PAL[p].b, counts[p]);
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "],\"cells\":[");
  int first = 1;
  for (int y = 0; y < N; y++) {
    for (int x = 0; x < N; x++) {
      pos += snprintf(json + pos, sizeof(json) - pos,
        "%s[%d,%d]", first ? "" : ",", chosen[y][x], height_plates[y][x]);
      first = 0;
    }
  }
  /* the artwork itself, for side-by-side comparison */
  pos += snprintf(json + pos, sizeof(json) - pos, "],\"art\":[");
  for (int y = 0; y < N; y++) {
    for (int x = 0; x < N; x++) {
      pos += snprintf(json + pos, sizeof(json) - pos, "%s[%d,%d,%d]", (x || y) ? "," : "",
        (int)(origR[y][x] + 0.5), (int)(origG[y][x] + 0.5), (int)(origB[y][x] + 0.5));
    }
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "]}");
  nb_set_json("mosaic_art", json);
  return 0;
}
